#include <vector>
#include <unordered_map>
#include <string>

using namespace std;

class Solution {
public:
    int maxEqualRowsAfterFlips(vector<vector<int>>& matrix) {
        unordered_map<string, int> count;
        for (auto& row : matrix) {
            string key;
            int flip = row[0];
            for (int val : row) key += (val ^ flip) + '0';
            count[key]++;
        }
        int res = 0;
        for (auto& [_, freq] : count)
            res = max(res, freq);
        return res;
    }
};
